import json,pathlib
root=pathlib.Path(__file__).parent
def link(href,title):return dict(href=href,title=title)
def section(title,text,table=None,links=None):
    s=dict(title=title,paragraphs=text.strip().split('\n\n'))
    if table:s['table']=dict(zip(('caption','headers','rows'),table))
    if links:s['links']=links
    return s
fish=dict(slug='kak-edyat-rybu-v-kaliningradskoy-oblasti',title='Как выбрать рыбное блюдо на Балтике',description='Рыбный обед в Калининградской области: закуски, уха, филе и целая рыба. Примеры меню, расчёт цены за 100 г и вопросы перед заказом.',intro='В Калининградской области рыбный обед можно собрать из небольшой закуски, тарелки ухи или горячего филе. Разбираем, какой формат выбрать под прогулку и общий стол, как прочитать цену за 100 граммов и что уточнить до заказа.',category='За столом',date='2026-11-05',imageAlt='Филе рыбы, уха и ржаной тост на светлом столе с видом на балтийский берег',takeaway='Сначала выберите формат обеда, затем сравните массу порции и способ расчёта цены. У целой рыбы уточните вес до приготовления и итоговую стоимость; у закуски — хватит ли её для самостоятельного приёма пищи.',related='/journal/ryba-baltiki-vidy/',relatedTitle='Какая рыба встречается в балтийском меню',sources=[dict(href=u,title=t,checked='2026-11-05') for u,t in [('https://local-baltic.ru/','Local Baltic: меню, цены и адрес в Светлогорске'),('https://korushka39.ru/','Бистро «Корюшка»: концепция, адрес и объявления'),('https://telegraph.rest/','«Телеграф»: официальный сайт ресторана в Зеленоградске')]],sections=[
section('Начните с того, сколько времени есть на обед','''Если после еды вы собираетесь продолжать прогулку, сначала решите, нужен ли полноценный обед или короткая остановка. Небольшая закуска с хлебом удобна для знакомства со вкусом, но не всегда заменяет горячее. Суп подходит для отдельной остановки за столом. Целую рыбу разумнее выбирать, когда есть время дождаться приготовления и спокойно разобрать порцию.

В компании полезно заранее договориться, пробует каждый своё блюдо или вы собираете общий стол. Во втором случае спросите, какие закуски можно разделить, сколько к ним подают хлеба и принесут ли дополнительные тарелки. Это помогает избежать ситуации, когда красивое блюдо рассчитано на одного, а попробовать его хотят четверо.

В таблице ниже — ориентиры для выбора, а не обещание скорости кухни. Время приготовления зависит от конкретного заказа и загрузки зала. Перед поездом или экскурсией назовите сотруднику время, к которому хотите закончить обед, и выбирайте из того, что реально успеют подать.''',('Как подобрать формат рыбного обеда',['Ваш план','Что посмотреть в меню','Что спросить'],[['Короткая остановка','Рыбная закуска с хлебом','Масса и время подачи'],['Обед после прогулки','Суп и небольшая закуска','Насколько сытная порция'],['Неспешный ужин','Горячее филе или целая рыба','Гарнир, кости и вес'],['Общий стол','Несколько блюд для деления','Размер порций и дополнительные тарелки']])),
section('Закуска, суп и горячее решают разные задачи','''У рыбной закуски важны способ приготовления и сопровождение. Паштет или риет обычно едят с хлебом; маринованную или солёную рыбу могут подавать с картофелем, луком и соусом. По одному названию трудно понять, получится лёгкая проба вкуса или достаточно плотная порция. Посмотрите выход блюда и уточните, входят ли дополнения в указанную цену.

Уха и сливочный рыбный суп тоже отличаются по ощущению от обеда. В одном случае основой будет бульон, в другом заметную роль играют сливки, овощи и густота. Лучше спросить, какая рыба используется сегодня, есть ли кости в порции и насколько острый бульон. Состав важнее красивого названия, особенно если у гостей разные предпочтения.

Филе проще сравнивать с другим горячим блюдом, если известны его масса и гарнир. Под общим весом в меню может подразумеваться вся тарелка вместе с овощами и соусом. При небольшом аппетите это не проблема, а для сытного обеда стоит отдельно выяснить, сколько в порции самой рыбы. Уточнение занимает минуту и делает выбор понятнее.'''),
section('Что можно увидеть в официальных меню','''Для примера возьмём опубликованное меню Local Baltic в Светлогорске, на улице Гагарина, 15. На момент проверки балтийская уха стоила 780 ₽, филе судака — 1 080 ₽, треска с овощным сопровождением — 1 420 ₽. Это три разных варианта заказа; сравнивать их только по цене без состава и выхода некорректно.

В Зеленоградске есть рыбное бистро «Корюшка» на Курортном проспекте, 26. На его официальном сайте опубликовано объявление о сравнении балтийской и чукотской корюшки. Сам пример хорошо показывает, почему адрес ресторана не доказывает происхождение каждой рыбы в меню. Наличие конкретного предложения на дату визита нужно уточнить отдельно.

На том же Курортном проспекте, в доме 29, находится ресторан «Телеграф». У него есть официальный раздел меню и возможность заранее выбрать формат визита. Эти адреса можно рассматривать как точки для самостоятельного сравнения. Мы проверяли опубликованную информацию, но не оцениваем обслуживание и не выдаём подборку за личную дегустацию.'''),
section('Цена за 100 граммов: считайте целую порцию','''Самая заметная ловушка при чтении рыбного меню — принять цену за 100 г за стоимость целой тарелки. В разделе целой рыбы Local Baltic для калкана или камбалы указаны 460 ₽ за 100 г сырого продукта. Итог зависит от массы выбранной рыбы. Это другой способ расчёта, чем фиксированная цена за порцию филе.

Пример арифметики: при массе 500 г расчёт по ставке 460 ₽ за 100 г даст 2 300 ₽. Здесь 500 г — условный вес для объяснения, а не размер рыбы в наличии. До подтверждения заказа попросите назвать фактическую массу, итог по рыбе и стоимость дополнений. Если гарнир оплачивается отдельно, прибавьте его к общей сумме.

Не делите цену целой рыбы на её сырой вес, пытаясь получить стоимость съедобного филе: в таком весе могут учитываться голова и кости. Для сравнения двух вариантов полезнее знать, на сколько человек рассчитана подача и что входит в комплект. Если бюджет ограничен, заранее обозначьте удобный предел суммы за весь заказ.''',('Условный расчёт при ставке 460 ₽ за 100 г',['Вес до приготовления','Расчёт','Стоимость рыбы'],[['400 г','4 × 460 ₽','1 840 ₽'],['500 г','5 × 460 ₽','2 300 ₽'],['600 г','6 × 460 ₽','2 760 ₽']])),
section('Местная кухня и местный улов — разные вопросы','''Ресторан может готовить в балтийском стиле и использовать рыбу из разных регионов. Это само по себе не делает блюдо хуже, но меняет ответ на вопрос «что именно я пробую». Если цель поездки — познакомиться с местным продуктом, спросите вид рыбы и место происхождения конкретной позиции, а не ориентируйтесь только на название заведения.

Сезонное меню также не означает, что вся рыба поймана сегодня. Важны информация поставщика и способ хранения продукта. Не стоит самостоятельно делать вывод о свежести по слову «балтийская», цвету соуса или фотографии. У сотрудника можно уточнить, какая рыба сейчас доступна и какие блюда готовят из неё в этот день.

Названия видов и способы подачи удобнее изучать отдельно от выбора ресторана. Тогда корюшка, судак и камбала перестают быть просто знакомыми словами в длинном списке. В нашем справочнике собраны ориентиры по рыбному меню области; здесь же основное внимание уделено заказу и расчёту стоимости.''',links=[link('/journal/ryba-baltiki-vidy/','Разобраться в видах рыбы балтийского меню')] ),
section('Как собрать рыбный стол для компании','''Начните с предпочтений гостей. Одни любят выраженный копчёный вкус, другим ближе мягкое филе; кто-то хочет суп, а кто-то пришёл только на закуску. Лучше распределить блюда заранее, чем заказывать всем одинаковую порцию ради удобства. Уточните отношение к костям, остроте и соусам, особенно если за столом есть дети.

Если берёте несколько блюд на всех, попросите подать закуски вместе, а горячее — после них. Так проще понять, сколько еды действительно нужно, и не занимать весь стол одновременно. Не добавляйте гарниры автоматически: в некоторых позициях овощи уже входят в состав. Отдельно согласуйте хлеб, напитки и приборы по числу гостей.

Для ужина в апартаментах порядок выбора похожий: сначала основное блюдо, затем дополнения и только после этого десерт. Рыбный пирог может быть самостоятельным вариантом общего стола, но его массу и порции нужно считать отдельно от ресторанных тарелок. Калькулятор на сайте поможет оценить количество пирогов без привязки к меню чужого ресторана.''',links=[link('/podbor/','Рассчитать пироги на компанию'),link('/journal/uzhin-v-semnyh-apartamentah/','Подготовить ужин в апартаментах')] ),
section('Пять вопросов перед подтверждением заказа','''Прежде чем соглашаться на предложение официанта, уточните пять вещей: какая рыба используется, сколько стоит вся порция, какой у неё выход, входит ли гарнир и сколько ждать подачи. Для целой рыбы добавьте вопрос о взвешивании до приготовления. Для общего стола — о количестве тарелок и возможности разделить блюдо на кухне.

Если планируете взять остаток с собой, заранее спросите об упаковке и рекомендациях заведения. Не включайте такую покупку в многочасовую прогулку без понимания условий перевозки. Когда главная цель — поесть у моря сразу после получения заказа, удобство подачи и возможность спокойно сесть важнее эффектной фотографии.

Цены и сведения из меню в этой статье проверены 5 ноября 2026 года по официальным страницам. Перед визитом откройте актуальную версию меню и уточните наличие выбранной позиции. Это особенно полезно для сезонной рыбы и предложений из новостного раздела: публикация на сайте не гарантирует, что блюдо осталось в продаже сегодня.''')])
breakfast=dict(slug='zavtrak-na-baltike',title='Завтрак на Балтике: Зеленоградск и Светлогорск',description='Где позавтракать перед прогулкой у моря: проверенные часы завтраков в Зеленоградске и Светлогорске, таблица адресов и план утреннего маршрута.',intro='Утро на Балтике удобнее планировать от времени завтрака, а не от красивой фотографии кафе. Сравниваем три официально опубликованных расписания в Зеленоградске, Светлогорске и Отрадном и собираем спокойный план перед прогулкой к морю.',category='За столом',date='2026-11-05',imageAlt='Омлет, сырники, хлеб и кофе на столе у балтийского променада с домиками и соснами',takeaway='Выберите город и нужный час, затем проверьте именно часы завтраков. Они могут заканчиваться раньше, чем закрывается ресторан. Для Отрадного отдельно заложите дорогу: это не центр Светлогорска.',related='/journal/gde-pozavtrakat-v-zelenogradske/',relatedTitle='Другие варианты завтрака в Зеленоградске',sources=[dict(href=u,title=t,checked='2026-11-05') for u,t in [('https://local-baltic.ru/','Local Baltic: время завтраков и адрес'),('https://grandmonopol.com/restaurant','«Гранд Монополь»: ресторан и расписание завтраков'),('https://v-coast.ru/','«Высокий берег»: кафе, часы и расположение в Отрадном')]],sections=[
section('Сначала город и время, потом меню','''Для завтрака перед пляжем важно не только то, что подают, но и где вы окажетесь после еды. В Зеленоградске можно остаться в городе и продолжить прогулку по выбранному маршруту. В Светлогорске нужно учесть расположение кафе относительно места проживания и спуска к морю. Поездка в Отрадное — отдельный небольшой маршрут, который лучше не добавлять в последний момент.

Начните с простого выбора: вы хотите выйти к морю пораньше, спокойно посидеть за столом или забрать еду с собой? Для раннего выхода подходят заведения с опубликованным началом завтраков. Для неспешного утра важнее запас до окончания подачи. Покупка навынос требует ещё одной проверки: можно ли получить нужное блюдо в подходящей упаковке.

Не стоит строить утро вокруг нескольких заведений в разных городах. Переезды, ожидание заказа и поиск столика займут часть времени, которое хотелось провести у воды. Выберите одну основную точку и запасной вариант поблизости. Такой план легче изменить, если утром захочется поспать дольше или погода окажется не для долгой прогулки.'''),
section('Три расписания, которые опубликованы на официальных сайтах','''На дату проверки Local Baltic в Светлогорске указывает ежедневные завтраки с 08:00 до 12:00. В ресторане «Гранд Монополь» в Зеленоградске завтрак подают с 09:00 до 12:00. Кафе «Высокого берега» в Отрадном публикует более короткое окно: с 09:00 до 11:00. Эти часы относятся к завтракам, а не ко всему времени работы заведений.

У «Высокого берега» отдельно сказано, что столик могут забронировать и те, кто не живёт в отеле. Для остальных точек условия посещения, наличие свободных мест и необходимость бронирования лучше уточнить перед выходом. Наличие ресторана при гостинице не позволяет автоматически переносить на него правила шведского стола или обслуживания в номере.

В таблице нет рейтинга и обещаний лучшего завтрака. Это три проверяемые отправные точки для планирования утра в разных частях побережья. Адреса, часы и ссылки помогают выбрать удобное место, а конкретные блюда, цены и доступность стола нужно смотреть в действующем меню заведения.''',('Часы завтраков: проверка 5 ноября 2026 года',['Место','Город и адрес','Завтраки','Для планирования'],[['Local Baltic','Светлогорск, Гагарина, 15','08:00–12:00','Самое раннее начало из этих трёх'],['«Гранд Монополь»','Зеленоградск, Володарского, 32','09:00–12:00','Утро в Зеленоградске'],['«Высокий берег»','Светлогорск, Отрадное, Нахимова, 1','09:00–11:00','Нужен отдельный маршрут в Отрадное']])),
section('Зеленоградск: завтрак перед городской прогулкой','''Если вы остановились в Зеленоградске, удобнее начать с расстояния от жилья до кафе. Не выбирайте точку на другом конце города только ради одного блюда: утром важнее понятная дорога и подходящее время. Учитывайте, что возвращение за забытыми вещами может занять больше времени, чем сам завтрак. Соберите всё для прогулки до выхода.

«Гранд Монополь» находится на улице Володарского, 32. Его опубликованное окно завтраков начинается в девять и заканчивается в полдень. Если хотите совместить еду с дальнейшими планами, не приходите к самому завершению подачи. Уточните, до какого времени принимают последний заказ именно на завтрак и сколько времени потребуется на выбранные блюда.

Для более подробного выбора точек в городе у нас есть отдельный гид по Зеленоградску. В нём удобно продолжить поиск, если адрес на Володарского не подходит к вашему маршруту. Здесь мы сравниваем утренние сценарии побережья, поэтому не дублируем большой список городских кафе и не смешиваем его с расписанием Светлогорска.''',links=[link('/journal/gde-pozavtrakat-v-zelenogradske/','Выбрать завтрак в Зеленоградске')] ),
section('Светлогорск и Отрадное: не путайте две точки на карте','''Утром в Светлогорске можно ориентироваться на Local Baltic на улице Гагарина, 15, если подходит начало завтраков с восьми. Перед выходом проверьте актуальное меню и возможность посещения в выбранный день. Время завтрака, основного меню и других форматов обслуживания может различаться даже у одного заведения. Не переносите часы из одного раздела сайта в другой.

«Высокий берег» расположен в районе Отрадное. Официальный сайт отеля указывает расстояние около трёх километров от центра Светлогорска. Поэтому этот вариант удобнее включать в утро, которое вы и так планируете провести в Отрадном, либо выбирать рядом с местом проживания. Запас времени до одиннадцати здесь особенно важен.

Не рассчитывайте переход между этими точками как несколько минут по прямой. Посмотрите реальный маршрут от двери жилья, а после завтрака — до нужного участка берега. Ветер, дождь, багаж и прогулка с ребёнком меняют удобство пути. Если хочется избежать лишних перемещений, оставьте дальнюю точку для другого утра, а сегодня выберите место рядом.''',links=[link('/journal/svetlogorsk-kaliningrad-edamarshrut/','Спланировать гастрономический день в Светлогорске')] ),
section('Что заказать перед пляжем, прогулкой или поездкой','''Меню лучше читать под планы ближайших часов. Перед спокойной прогулкой можно выбрать привычный завтрак и напиток. Перед долгой поездкой полезно понять, когда будет следующая возможность нормально поесть. Если после кофе и выпечки вы обычно быстро голодны, добавьте подходящее основное блюдо, а сладкое оставьте дополнением. Универсального завтрака для всех здесь нет.

Для семьи удобнее заранее обсудить, кто что действительно хочет. Один большой заказ на общий стол может не решить задачу, если дети не едят соус или взрослые предпочитают разные блюда. Уточните возможность подать соус отдельно, размер порции и состав. Не предполагайте, что детское меню или половинная порция доступны в любом кафе при отеле.

Если хочется попробовать местный вкус, выбирайте его осознанно, а не по обязательному списку туриста. Сыр, хлеб, рыбная закуска или выпечка могут дополнить утро, но наличие конкретного продукта нужно проверить в меню. В нашем отдельном материале о хлебе разобраны форматы покупки для завтрака, общего стола и дороги.''',('Планы после завтрака и вопросы к заказу',['После еды вы…','На что обратить внимание','Что уточнить'],[['Идёте гулять','Привычный размер завтрака','Время подачи'],['Едете на экскурсию','Достаточно ли еды до следующей остановки','Можно ли подать всё одновременно'],['Завтракаете с детьми','Понятный состав и удобная порция','Соусы отдельно и размер блюда'],['Берёте еду с собой','Упаковка и приборы','Какие позиции подходят навынос']]),links=[link('/journal/hleb-i-vypechka-kaliningradskoy-oblasti/','Выбрать хлеб и выпечку к завтраку')] ),
section('Как сравнить стоимость без выдуманного среднего чека','''Утренний бюджет удобнее считать по вашему заказу, а не по слову «средний чек» в карточке заведения. Выпишите цену основного блюда, напитка и дополнений для каждого гостя. Если хотите разделить десерт, добавьте его один раз. Проверьте, входит ли напиток в комплексный завтрак или оплачивается отдельно: похожие названия предложений не означают одинаковый состав.

Например, для двух человек формула может выглядеть так: два основных блюда плюс два напитка плюс одна общая выпечка. Подставьте текущие цены из меню и сравните с другим местом по тому же набору. Это будет ваш расчёт, а не условная цифра на человека, которая может не учитывать кофе, добавки или другой размер порции.

В этой статье мы не публикуем неподтверждённые цены на завтраки: официально проверены адреса и часы, а меню может обновляться отдельно. Перед оплатой уточняйте стоимость замен и добавок. Для завтрака в апартаментах можно использовать тот же подход: сначала состав стола и количество гостей, затем продукты и дополнительные покупки.'''),
section('Если завтрак остаётся в апартаментах','''Иногда удобнее поесть дома, а к морю выйти сразу после завтрака. С вечера проверьте, что есть на кухне: чайник, чашки, нож, доска и тарелки. Если планируете разогрев, посмотрите, какая техника доступна и подходит ли для выбранной еды. Описание апартаментов не всегда заменяет проверку на месте.

Подберите продукты, которые нравятся всем гостям и не требуют сложной готовки. Хлеб или выпечку удобно дополнить тем, что уже есть в холодильнике; напитки можно приготовить по очереди, пока накрываете стол. Не покупайте лишнее только ради красивой раскладки. После завтрака всё равно придётся убрать посуду и решить, что делать с остатками перед поездкой.

Для поездки на несколько дней полезно разделить планы: один завтрак в кафе, другой дома, третий по пути к экскурсии. Так проще познакомиться с городом и не превращать каждое утро в поиск свободного столика. Подробный список подготовки кухни собран в нашем руководстве для апартаментов; его можно использовать и для завтрака, и для ужина.''',links=[link('/journal/uzhin-v-semnyh-apartamentah/','Проверить кухню и посуду в апартаментах')] ),
section('Проверьте план утром перед выходом','''Откройте официальный сайт выбранного места, посмотрите часы завтраков и при необходимости уточните последний заказ. Сверьте адрес с маршрутом от жилья. Если идёте большой компанией, спросите о столике заранее. Когда времени мало, сразу обозначьте, к какому часу нужно закончить: это помогает выбрать подходящие блюда без спешки.

Запасной вариант должен быть действительно удобным. Лучше соседнее кафе с понятным меню, чем адрес в другом городе, до которого ещё предстоит добраться. Если утро холодное или дождливое, выбирайте возможность спокойно сесть внутри. Если погода располагает к прогулке, сначала позавтракайте, а напиток навынос при желании купите уже по пути.

Расписания и адреса в таблице проверены 5 ноября 2026 года по официальным страницам трёх заведений. Это основа для планирования, а не гарантия неизменного графика. Особенно внимательно проверяйте праздничные дни и сезонные изменения. Спокойное утро начинается с одного подходящего места и реалистичного запаса времени, а не с попытки успеть всё побережье до полудня.''')])
